#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int key[] = {8, 3, 10, 6}, l[] = {1, -1, -1, -1}, r[] = {2, 3, -1, -1};
    int cur = 0, c = 0;
    while (cur != -1) {
        c++;
        if (key[cur] == 6) {
            break;
        }
        cur = 6 < key[cur] ? l[cur] : r[cur];
    }
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int key[] = {8, 3, 10, 1}, left[] = {1, 3, -1, -1};
    int cur = 0;
    while (left[cur] != -1) {
        cur = left[cur];
    }
    printf("%d\n", key[cur]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int a[] = {1, 3, 6, 8, 9, 10, 14}, next = -1;
    for (int i = 6; i >= 0; i--) {
        if (a[i] > 8) {
            next = a[i];
        }
    }
    printf("%d\n", next);
    return 0;
}
